from functools import lru_cache

items='abcdef'
outs=set()
def dfs(i, stack, out, poprun):
    if i==len(items) and not stack:
        outs.add(out)
        return
    if i < len(items):
        dfs(i+1, stack+(items[i],), out, 0)
    if stack and poprun<2:
        dfs(i, stack[:-1], out+stack[-1], poprun+1)
dfs(0, tuple(), '', 0)
len(outs), sorted([x for x in ['afedcb','dcebfa','cbdaef','bcaefd'] if x in outs]), [x for x in ['afedcb','dcebfa','cbdaef','bcaefd'] if x not in outs]

