def stack_perms(n):
    items=list(range(1,n+1))
    outs=set()
    def dfs(i, stack, out):
        if i==n and not stack:
            outs.add(tuple(out)); return
        if i<n:
            dfs(i+1, stack+(items[i],), out)
        if stack:
            dfs(i, stack[:-1], out+[stack[-1]])
    dfs(0, tuple(), [])
    return outs
for n in range(3,8):
    vals=sorted(set(o[2] for o in stack_perms(n) if o[1]==3))
    seqs=[o for o in stack_perms(n) if o[1]==3]
    print(n, vals, len(vals), len(seqs), sorted(seqs)[:20])

